228	                  break;
229	                }
230	                case TimelineDiff_Tags.Set: {
231	                  const { index, value } = diff.inner;
232	                  const ev = toEventItem(value);
233	                  timelineItems[index] = ev;
234	
235	                  // transactionId -> eventId transition can arrive in an order where
236	                  // a stale local echo still exists elsewhere in the list.
237	                  if (
238	                    ev?.isOwn &&
239	                    !ev.localSendState &&
240	                    pendingTransactionIdsQueue.current.length > 0
241	                  ) {
242	                    const txId = pendingTransactionIdsQueue.current.shift();
243	                    if (txId) {
244	                      const txIndex = timelineItems.findIndex((item) => {
245	                        if (!item) return false;
246	                        return getItemUniqueKey(item) === txId;
247	                      });
248	                      if (txIndex !== -1) {
249	                        timelineItems[txIndex] = ev;
250	                      }
251	                    }
252	                  }
253	                  break;
254	                }
255	                case TimelineDiff_Tags.Remove: {
256	                  const { index: removeIndex } = diff.inner;
257	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
258	                    timelineItems.splice(removeIndex, 1);
259	                  }
260	                  break;
261	                }
262	                case TimelineDiff_Tags.PushFront: {
263	                  const { value } = diff.inner;
264	                  timelineItems.unshift(toEventItem(value));
265	                  break;
266	                }
267	                case TimelineDiff_Tags.PushBack: {
268	                  const { value } = diff.inner;
269	                  const ev = toEventItem(value);
270	                  timelineItems.push(ev);
271	                  if (ev) {
272	                    const txId = getTransactionId(ev);
273	                    if (txId) {
274	                      pendingTransactionIdsQueue.current.push(txId);
275	                    }
276	                  }
277	                  break;
278	                }
279	                case TimelineDiff_Tags.PopFront: {
280	                  timelineItems.shift();
281	                  break;
282	                }
283	                case TimelineDiff_Tags.PopBack: {
284	                  timelineItems.pop();
285	                  break;
286	                }
287	                case TimelineDiff_Tags.Reset: {
288	                  const resetItems = diff.inner.values;
289	                  pendingTransactionIdsQueue.current = [];
290	                  timelineItemsRef.current = resetItems.map(toEventItem);
291	
292	                  const eventItems = timelineItemsRef.current.filter(
293	                    (i): i is EventTimelineItem => !!i,
294	                  );
295	                  pendingTransactionIdsQueue.current = eventItems
296	                    .map(getTransactionId)
297	                    .filter((id): id is string => !!id);
298	                  break;
299	                }
300	                case TimelineDiff_Tags.Truncate: {
301	                  const { length: cut } = diff.inner;
302	                  timelineItems.length = cut;
303	                  break;
304	                }
305	                case TimelineDiff_Tags.Clear: {
306	                  timelineItemsRef.current = [];
307	                  pendingTransactionIdsQueue.current = [];
308	                  eventIdsRef.current = new Set();
309	                  setEvents([]);
310	                  break;
311	                }
312	                default:
313	                  console.log("Unknown timeline change type:", change);
314	              }
315	            });
