318	              if (rebuildTimerRef.current) {
319	                clearTimeout(rebuildTimerRef.current);
320	              }
321	              rebuildTimerRef.current = setTimeout(
322	                rebuildEventsFromTimelineItems,
323	                0,
324	              );
325	            }
326	
327	            if (ENABLE_TIMELINE_DEBUG) {
328	              const afterCount = timelineItemsRef.current.length;
329	              const tags = diffs.map((d) => d.tag).join(", ");
330	              console.log(
331	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
332	              );
333	            }
334	          },
335	        });
336	
337	        // Paginate after the listener is set up so events flow through it.
338	        // Loop until we have at least MIN_INITIAL_EVENTS or reach the start.
339	        isPaginatingRef.current = true;
340	        (async () => {
341	          try {
342	            let hitStart = false;
343	            while (!isDisposed && !hitStart) {
344	              hitStart = await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
345	              if (hitStart) {
346	                reachedStartRef.current = true;
347	                break;
348	              }
349	              const eventCount =
350	                timelineItemsRef.current.filter(Boolean).length;
351	              if (eventCount >= MIN_INITIAL_EVENTS) break;
352	            }
353	          } catch (error) {
354	            if (!isDisposed) {
355	              console.warn("Failed to load initial messages:", error);
356	            }
357	          } finally {
358	            isPaginatingRef.current = false;
359	          }
360	        })();
361	      } catch (error) {
362	        console.error("Failed to initialize room timeline:", error);
363	        offlineToastHelper("Failed to load the messages. Please try again.");
364	        NavigationContainerRef.goBack();
365	        return null;
366	      }
367	    };
368	
369	    initRoomTimeline();
370	
371	    return () => {
372	      isDisposed = true;
373	      timelineListenerHandle?.cancel?.();
374	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
375	      timelineRef.current = null;
376	      timelineItemsRef.current = [];
377	      isPaginatingRef.current = false;
378	      reachedStartRef.current = false;
379	    };
380	  }, [rebuildEventsFromTimelineItems, room, roomId]);
381	
382	  useEffect(() => {
383	    markAsRead().catch(console.error);
384	    room?.isDirect().then(setIsDirect).catch(console.error);
385	  }, [room, markAsRead]);
386	
387	  return {
388	    events,
389	    timelineRef,
390	    isPaginatingRef,
391	    reachedStartRef,
392	    isDirect,
393	    loadMoreMessages,
394	    markAsRead,
395	  };
396	};
