357	          ? {
358	              height: BigInt(thumbnailHeight),
359	              width: BigInt(thumbnailWidth),
360	              mimetype: "image/jpeg",
361	              size: BigInt(thumbnailSize),
362	            }
363	          : undefined,
364	        thumbnailSource: undefined,
365	        blurhash,
366	      });
367	      await videoHandle.join();
368	    } else {
369	      const imageHandle = timeline.sendImage(
370	        fileSource,
371	        new UploadSource.File({
372	          filename: decodeURIComponent(asset.uri.replace("file://", "")),
373	        }),
374	        {
375	          height: BigInt(assetHeight),
376	          width: BigInt(assetWidth),
377	          mimetype: type,
